// Exclut tout profil signalant "Open to Work" — structure (badge Apify) ou texte (headline/summary/about).
function isOpenToWork(p) {
  if (p == null) return false;
  if (p.openToWork === true || p.open_to_work === true || p.isOpenToWork === true) return true;
  if (Array.isArray(p.badges) && p.badges.some(b => /open.?to.?work/i.test(String(b)))) return true;

  const fields = [p.headline, p.summary, p.about, p.title];
  const text = fields.filter(Boolean).join(' ').toLowerCase();
  const patterns = [
    /open\s*to\s*work/i,
    /#opentowork/i,
    /ouvert(e)?\s+aux\s+opportunit/i,
    /\u00e0\s+l['\u2019]\u00e9coute\s+du\s+march/i,
    /en\s+recherche\s+d['\u2019]emploi/i,
    /disponible\s+imm\u00e9diatement/i,
    /recherche\s+active(?:ment)?\s+un\s+poste/i,
  ];
  return patterns.some(re => re.test(text));
}

const items = $input.all();
return items.filter(item => !isOpenToWork(item.json));

const OR_KEY = "YOUR_OPENROUTER_API_KEY";
const SYSTEM_PROMPT = "Tu es un expert en qualification de leads LinkedIn B2B pour une offre CLIENT ACQUISITION OS (infrastructure commerciale IA a base mensuelle).\n\nQualifie OUI uniquement si la personne est dirigeant B2B (fondateur, CEO, dirigeant, associe) d'une entreprise francophone avec un cycle de vente clair, effectif au moins 5 salaries (pas de plafond).\n\nQualifie NON si : effectif < 5 salaries, salarie sans pouvoir de decision, hors marche francophone, hors B2B, profil en recherche d'emploi.\n\nReponds UNIQUEMENT en JSON strict, sans texte autour : {\"icp\": \"oui\" ou \"non\", \"raison\": \"1 phrase courte en francais expliquant pourquoi\"}";

async function classify(p) {
  const bio = (p.headline || '') + ((p.currentPosition && p.currentPosition[0] && p.currentPosition[0].description) ? ' | ' + p.currentPosition[0].description : '');
  try {
    const resp = await this.helpers.httpRequest({
      method: 'POST',
      url: 'https://openrouter.ai/api/v1/chat/completions',
      headers: { 'Authorization': 'Bearer ' + OR_KEY, 'Content-Type': 'application/json' },
      body: JSON.stringify({
        model: 'anthropic/claude-haiku-4.5',
        messages: [
          { role: 'system', content: SYSTEM_PROMPT },
          { role: 'user', content: 'Nom: ' + (p.firstName || '') + ' ' + (p.lastName || '') + '\nBio: ' + bio }
        ],
        temperature: 0.1,
        max_tokens: 150
      }),
      json: true,
    });
    const content = (resp.choices && resp.choices[0] && resp.choices[0].message.content) || '';
    const match = content.match(/\{[\s\S]*\}/);
    if (match) {
      const parsed = JSON.parse(match[0]);
      return { icp: (parsed.icp || '').toLowerCase().trim() === 'oui' ? 'oui' : 'non', raison: parsed.raison || '' };
    }
  } catch (e) {}
  return { icp: 'non', raison: '' };
}

const items = $input.all();
const out = [];
for (const item of items) {
  const p = item.json;
  const result = await classify.call(this, p);
  if (result.icp !== 'oui') continue;
  const pos = (p.currentPosition && p.currentPosition[0]) || {};
  const bio = (p.headline || '') + (pos.description ? ' | ' + pos.description : '');
  out.push({
    json: {
      id: p.id,
      name: (p.firstName || '') + ' ' + (p.lastName || ''),
      linkedinUrl: p.linkedinUrl,
      publicIdentifier: (p.linkedinUrl || '').match(/linkedin\.com\/in\/([^/?]+)/)?.[1] || '',
      headline: p.headline || '',
      bio: bio,
      company: pos.companyName || '',
      companyLinkedinUrl: pos.companyLinkedinUrl || '',
      icpMatch: 'oui',
      raisonIcp: result.raison,
      targetAccountName: p.targetAccountName,
      targetAccountId: p.targetAccountId
    }
  });
}
return out;

