const key = "YOUR_UNIPILE_API_KEY";
const base = "https://YOUR_UNIPILE_DSN";
const results = [];

for (const item of $input.all()) {
  const p = item.json;
  let employeeCount = null;
  const companyPublicId = (p.companyLinkedinUrl || '').match(/linkedin\.com\/company\/([^/?]+)/)?.[1] || '';

  if (companyPublicId) {
    try {
      const resp = await this.helpers.httpRequest({
        method: 'GET',
        url: base + '/api/v1/linkedin/company/' + companyPublicId + '?account_id=' + p.targetAccountId,
        headers: { 'X-API-KEY': key },
        json: true
      });
      employeeCount = resp.employee_count != null ? resp.employee_count : null;
    } catch (e) {
      employeeCount = null;
    }
  }

  if (!companyPublicId || employeeCount === null) {
    results.push({ json: { ...p, employeeCount: null } });
    continue;
  }

  if (employeeCount < 5) continue;

  results.push({ json: { ...p, employeeCount } });
}

return results;

const key = "YOUR_UNIPILE_API_KEY";
const base = "https://YOUR_UNIPILE_DSN";
const TG_TOKEN = "YOUR_TELEGRAM_BOT_TOKEN";
const TG_CHAT = "YOUR_TELEGRAM_CHAT_ID";

async function sendTelegram(text) {
  try {
    await this.helpers.httpRequest({
      method: 'POST',
      url: 'https://api.telegram.org/bot' + TG_TOKEN + '/sendMessage',
      headers: { 'Content-Type': 'application/json' },
      body: { chat_id: TG_CHAT, text },
      json: true,
    });
  } catch (e) {}
}

let sentIds = new Set();
try {
  const resp = await this.helpers.httpRequest({
    method: 'GET',
    url: base + '/api/v1/users/invite/sent?account_id=0jzffBkbTwyFztGyme5IDA&limit=200',
    headers: { 'X-API-KEY': key },
    json: true,
  });
  (resp.items || []).forEach(i => { if (i.invited_user_id) sentIds.add(i.invited_user_id); });
} catch (e) {}

const staticData = $getWorkflowStaticData('global');
staticData.triedIds = staticData.triedIds || {};
const now = Date.now();
const TWELVE_HOURS = 12 * 3600000;
for (const id of Object.keys(staticData.triedIds)) {
  if (now - staticData.triedIds[id] > TWELVE_HOURS) delete staticData.triedIds[id];
}
const triedRecently = new Set(Object.keys(staticData.triedIds));

const parisDateStr = new Intl.DateTimeFormat('fr-CA', { timeZone: 'Europe/Paris' }).format(new Date());
if (staticData.dailyInviteDate !== parisDateStr) {
  staticData.dailyInviteDate = parisDateStr;
  staticData.dailyInviteCount = 0;
}
const DAILY_LIMIT = 18;
const remainingToday = Math.max(DAILY_LIMIT - (staticData.dailyInviteCount || 0), 0);

const items = $input.all();
const fresh = items.filter(i => !sentIds.has(i.json.id) && !triedRecently.has(i.json.id));
const picked = fresh.slice(0, remainingToday);

if (remainingToday === 0) {
  await sendTelegram.call(this, 'Jules Brommet : limite quotidienne de 18 demandes de connexion deja atteinte, aucun envoi ce run.');
}

// Delai aleatoire de 2 a 3 minutes entre chaque demande de connexion sur ce compte
// (decision explicite : rythme volontairement court sur un meme compte, plutot que
// l'etalement sur toute la journee jusqu'a 19h qui exposait aux Wait n8n bloques trop longtemps).
let cursorMs = 0;
for (let idx = 0; idx < picked.length; idx++) {
  const delaySeconds = 120 + Math.random() * 60; // 2 to 3 minutes
  cursorMs += delaySeconds * 1000;
  picked[idx].json._waitSeconds = Math.round(cursorMs / 1000);
}
if (picked.length) picked[0].json._runStartMs = Date.now();
for (let idx = 1; idx < picked.length; idx++) picked[idx].json._runStartMs = picked[0].json._runStartMs;

return picked;

const key = "YOUR_UNIPILE_API_KEY";
const base = "https://YOUR_UNIPILE_DSN";
const lead = $input.item.json;
const accountId = lead.targetAccountId || lead.accountId || '0jzffBkbTwyFztGyme5IDA';
// RESOLVE_PROVIDER_ID_FIX: leads coming from the Google Sheet only have "Lien profil LKD"
// (no .id / .linkedinUrl field, those only exist right after the Unipile search node).
// Resolve the real provider_id from the public_identifier before inviting.
let providerId = lead.id;
if (!providerId) {
  const sheetUrl = lead['Lien profil LKD'] || lead.linkedinUrl || '';
  const m = sheetUrl.match(/linkedin\.com\/in\/([^\/?#]+)/);
  const publicId = m ? m[1] : '';
  if (publicId) {
    try {
      const profileResp = await this.helpers.httpRequest({
        method: 'GET',
        url: base + '/api/v1/users/' + encodeURIComponent(publicId) + '?account_id=' + accountId,
        headers: { 'X-API-KEY': key },
        json: true,
      });
      providerId = profileResp.provider_id;
    } catch (e) {}
  }
}


const RETRYABLE_TYPES = ['errors/rate_limit', 'errors/internal_error'];
const MAX_ATTEMPTS = 3;

let status = '';
let sent = false;
let resp = null;

for (let attempt = 1; attempt <= MAX_ATTEMPTS && !sent; attempt++) {
  resp = await this.helpers.httpRequest({
    method: 'POST',
    url: base + '/api/v1/users/invite',
    headers: { 'X-API-KEY': key, 'Content-Type': 'application/json' },
    body: { provider_id: providerId, account_id: accountId },
    json: true,
    ignoreHttpStatusErrors: true,
  });

  if (!resp || resp.status == null || resp.status < 400) {
    sent = true;
    status = 'fait';
    break;
  }

  const errType = (resp.type || '').toLowerCase();
  const errDetail = (resp.detail || resp.title || '').toLowerCase();
  const haystack = errType + ' ' + errDetail;

  // Hard stop: real LinkedIn/Unipile quota or account block.
  if (haystack.includes('quota') || haystack.includes('limit_reached') || haystack.includes('daily') || haystack.includes('weekly')) {
    status = 'LIMITE ATTEINTE';
    break;
  }
  if (haystack.includes('account_blocked') || haystack.includes('account_restricted') || haystack.includes('suspended') || haystack.includes('account_disabled')) {
    status = 'BLOQUE - compte restreint';
    break;
  }

  // Benign / already-known cases: no retry needed, just record and move on.
  if (haystack.includes('already_invited') || haystack.includes('already_connected') || haystack.includes('invitation_already_sent') || haystack.includes('pending_invitation') || haystack.includes('already_invited_recently') || haystack.includes('cannot_resend_yet')) {
    status = 'deja fait avant';
    break;
  }
  if (haystack.includes('email_required') || haystack.includes('must_send_invitation_request_with_email')) {
    status = 'email requis';
    break;
  }
  if (haystack.includes('not_found') || errDetail.includes('404')) {
    status = 'compte introuvable';
    break;
  }
  if (haystack.includes('private') || haystack.includes('restricted_profile')) {
    status = 'compte prive';
    break;
  }
  if (haystack.includes('invalid_recipient') || haystack.includes('cannot be reached')) {
    status = 'profil non joignable';
    break;
  }

  // Genuinely retryable (rate limit / transient) -> backoff and retry.
  if (RETRYABLE_TYPES.some(t => errType.includes(t)) && attempt < MAX_ATTEMPTS) {
    const backoffMs = attempt === 1 ? 15000 : 45000;
    await new Promise(r => setTimeout(r, backoffMs));
    continue;
  }

  // Unrecognized error: record the real type/detail instead of "unknown".
  status = 'erreur ' + resp.status + ' ' + (resp.type || resp.title || 'inconnue');
  break;
}

return [{
  json: {
    ...lead,
    _inviteSent: sent,
    _inviteSkippedReason: sent ? null : status,
  }
}];

const staticData = $getWorkflowStaticData('global');
staticData.triedIds = staticData.triedIds || {};
const lead = $('Boucle 1 lead a la fois').item.json;
if (lead && lead.id) {
  staticData.triedIds[lead.id] = Date.now();
}
if ($input.item.json._inviteSent) {
  staticData.dailyInviteCount = (staticData.dailyInviteCount || 0) + 1;
} else {
  const TG_TOKEN = "YOUR_TELEGRAM_BOT_TOKEN";
  const TG_CHAT = "YOUR_TELEGRAM_CHAT_ID";
  try {
    await this.helpers.httpRequest({
      method: 'POST',
      url: 'https://api.telegram.org/bot' + TG_TOKEN + '/sendMessage',
      headers: { 'Content-Type': 'application/json' },
      body: { chat_id: TG_CHAT, text: 'Jules Brommet : echec envoi demande de connexion pour ' + (lead.name || lead.linkedinUrl || lead.id) + ' - raison: ' + ($input.item.json._inviteSkippedReason || 'inconnue') },
      json: true,
    });
  } catch (e) {}
}
// Hard stop: si le compte est vraiment bloque/quota atteint, on arrete net
// le traitement des leads suivants de ce run plutot que de continuer a taper
// dans un compte deja restreint (reprend la logique du template de reference).
const HARD_STOP_REASONS = ['LIMITE ATTEINTE', 'BLOQUE - compte restreint'];
const reason = $input.item.json._inviteSkippedReason;
if (reason && HARD_STOP_REASONS.includes(reason)) {
  const TG_TOKEN2 = "YOUR_TELEGRAM_BOT_TOKEN";
  const TG_CHAT2 = "YOUR_TELEGRAM_CHAT_ID";
  try {
    await this.helpers.httpRequest({
      method: 'POST',
      url: 'https://api.telegram.org/bot' + TG_TOKEN2 + '/sendMessage',
      headers: { 'Content-Type': 'application/json' },
      body: { chat_id: TG_CHAT2, text: '[STOP] ' + 'Prospection ICP - Scraping + Demandes de connexion' + ' : ' + reason + ' - arret immediat des demandes de connexion pour ce run.' },
      json: true,
    });
  } catch (e) {}
  return [];
}
return [{ json: $input.item.json }];

const APIFY_TOKEN = "YOUR_APIFY_TOKEN";
const ACTOR_ID = "M2FMdjRVeF1HPGFcc"; // harvestapi/linkedin-profile-search
const key = "YOUR_UNIPILE_API_KEY";
const base = "https://YOUR_UNIPILE_DSN";
const accountId = "0jzffBkbTwyFztGyme5IDA";
const searchQuery = "consultant automatisation IA startup France";
const targetAccountName = "Jules";

function parseWorkDurationMonths(pos) {
  const years = (pos && pos.tenureAtPosition && pos.tenureAtPosition.numYears) || 0;
  const months = (pos && pos.tenureAtPosition && pos.tenureAtPosition.numMonths) || 0;
  return Math.round(years * 12 + months);
}
function durationLabel(months) {
  const yr = Math.floor(months / 12);
  const mo = months % 12;
  let s = '';
  if (yr > 0) s += yr + ' yr ';
  if (mo > 0) s += mo + ' mo';
  return s.trim();
}

// Advance the search page every run so we don't keep re-scraping the same
// pool of profiles (was stuck re-fetching page 1 every time -> only
// already-tried leads, 0 new invites). maxItems raised to widen the pool.
const staticData = $getWorkflowStaticData('global');
const currentPage = staticData._apifySearchPage || 1;

let profiles = [];
try {
  const startRes = await this.helpers.httpRequest({
    method: 'POST',
    url: 'https://api.apify.com/v2/acts/' + ACTOR_ID + '/runs?token=' + APIFY_TOKEN,
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({
      profileScraperMode: 'Short',
      searchQuery: searchQuery,
      maxItems: 50,
      startPage: currentPage,
      takePages: 2,
    }),
    json: true,
  });
  const runId = startRes.data.id;

  let status = 'RUNNING';
  let datasetId = startRes.data.defaultDatasetId;
  for (let i = 0; i < 24 && (status === 'RUNNING' || status === 'READY'); i++) {
    await new Promise(r => setTimeout(r, 10000));
    const statusRes = await this.helpers.httpRequest({
      method: 'GET',
      url: 'https://api.apify.com/v2/actor-runs/' + runId + '?token=' + APIFY_TOKEN,
      json: true,
    });
    status = statusRes.data.status;
    datasetId = statusRes.data.defaultDatasetId;
  }

  if (status === 'SUCCEEDED') {
    const itemsRes = await this.helpers.httpRequest({
      method: 'GET',
      url: 'https://api.apify.com/v2/datasets/' + datasetId + '/items?token=' + APIFY_TOKEN,
      json: true,
    });
    profiles = Array.isArray(itemsRes) ? itemsRes : [];
  }

  // Advance 2 pages next run (we requested takePages:2); loop back to page 1 once dry.
  staticData._apifySearchPage = profiles.length > 0 ? currentPage + 2 : 1;
} catch (e) {
  staticData._apifySearchPage = 1;
  return [];
}

const out = [];
for (const p of profiles) {
  const pos = (p.currentPositions && p.currentPositions[0]) || {};
  const months = parseWorkDurationMonths(pos);

  let providerId = null;
  let publicIdentifier = '';
  let headline = pos.title || '';
  let followerCount = 0;
  try {
    const profile = await this.helpers.httpRequest({
      method: 'GET',
      url: base + '/api/v1/users/' + encodeURIComponent(p.id) + '?account_id=' + accountId,
      headers: { 'X-API-KEY': key },
      json: true,
    });
    providerId = profile.provider_id;
    publicIdentifier = profile.public_identifier || '';
    headline = profile.headline || headline;
    followerCount = profile.follower_count || 0;
  } catch (e) {
    continue;
  }
  if (!providerId) continue;

  out.push({
    json: {
      id: providerId,
      firstName: p.firstName || '',
      lastName: p.lastName || '',
      linkedinUrl: publicIdentifier ? ('https://www.linkedin.com/in/' + publicIdentifier) : p.linkedinUrl,
      headline: headline,
      followerCount: followerCount,
      currentPosition: [{
        position: pos.title || '',
        description: pos.description || '',
        duration: durationLabel(months),
        employmentType: pos.current ? 'Current' : '',
        companyName: pos.companyName || '',
        companyLinkedinUrl: '',
      }],
      targetAccountName: targetAccountName,
      targetAccountId: accountId,
    }
  });
}
return out;

const key = "YOUR_UNIPILE_API_KEY";
const base = "https://YOUR_UNIPILE_DSN";
const accountId = "0jzffBkbTwyFztGyme5IDA";
const searchQuery = "consultant automatisation IA startup France";
const targetAccountName = "Jules Brommet";

function parseWorkDurationMonths(exp) {
  if (!exp || !exp.start) return 0;
  const start = new Date(exp.start);
  const end = exp.end ? new Date(exp.end) : new Date();
  if (isNaN(start.getTime())) return 0;
  const months = (end.getFullYear() - start.getFullYear()) * 12 + (end.getMonth() - start.getMonth());
  return Math.max(months, 0);
}
function durationLabel(months) {
  const yr = Math.floor(months / 12);
  const mo = months % 12;
  let s = '';
  if (yr > 0) s += yr + ' yr ';
  if (mo > 0) s += mo + ' mo';
  return s.trim();
}

let searchResults = [];
try {
  const resp = await this.helpers.httpRequest({
    method: 'POST',
    url: base + '/api/v1/linkedin/search?account_id=' + accountId,
    headers: { 'X-API-KEY': key, 'Content-Type': 'application/json' },
    body: { api: 'classic', category: 'people', keywords: searchQuery },
    json: true,
  });
  searchResults = (resp.items || []).filter(i => i.type === 'PEOPLE').slice(0, 40);
} catch (e) {
  return [];
}

const out = [];
for (const person of searchResults) {
  let profile = null;
  try {
    profile = await this.helpers.httpRequest({
      method: 'GET',
      url: base + '/api/v1/users/' + encodeURIComponent(person.id) + '?account_id=' + accountId + '&linkedin_sections=experience',
      headers: { 'X-API-KEY': key },
      json: true,
    });
  } catch (e) {
    continue;
  }
  if (!profile) continue;

  const exp = (profile.work_experience && profile.work_experience[0]) || {};
  const months = parseWorkDurationMonths(exp);

  out.push({
    json: {
      id: profile.provider_id,
      firstName: profile.first_name || '',
      lastName: profile.last_name || '',
      linkedinUrl: 'https://www.linkedin.com/in/' + (profile.public_identifier || ''),
      headline: profile.headline || '',
      followerCount: profile.follower_count || 0,
      location: profile.location || (profile.primary_locale && profile.primary_locale.country) || '',
      currentPosition: [{
        position: exp.position || '',
        description: exp.description || '',
        duration: durationLabel(months),
        employmentType: exp.status || '',
        companyName: exp.company || '',
        companyLinkedinUrl: exp.company_id ? ('https://www.linkedin.com/company/' + exp.company_id) : '',
      }],
      targetAccountName: targetAccountName,
      targetAccountId: accountId,
    }
  });
}
return out;
